/**
 * Tìm lỗ hổng kiến thức và gốc rễ. THUẦN — chép sang Edge Function.
 *
 * Với mỗi kĩ năng 'can-on': lần theo prereqs; kĩ năng nền "yếu" (≥ 3 lần làm và: can-on, hoặc dang-hoc với p < 0.7) yếu nhất
 * trở thành gốc, rồi lần tiếp từ gốc đó. Không thấy nền yếu → thử `rootSkill` của quan niệm sai hay gặp nhất
 * (nếu kĩ năng đó cũng yếu). Gốc = cuối chuỗi.
 */
import { MISCONCEPTIONS, SKILL_BY_CODE, type KnowledgeGap, type Misconception, type MisconceptionCount, type Skill, type SkillMastery } from '../scoring/contracts.ts';
import { GAP_P, MIN_ATTEMPTS, ROOT_WEAK_P } from './constants.ts';

export function isWeak(m: SkillMastery | undefined): boolean {
  if (!m || m.attempts < MIN_ATTEMPTS) return false;
  return m.level === 'can-on' || (m.level === 'dang-hoc' && m.p < ROOT_WEAK_P);
}

export function topMisconceptions(counts: Record<string, number>, catalog: Record<string, Misconception> = MISCONCEPTIONS, n = 3): MisconceptionCount[] {
  return Object.entries(counts)
    .filter(([, c]) => c > 0)
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, n)
    .map(([code, count]) => ({ code, count, text: catalog[code]?.text ?? code, kidHint: catalog[code]?.kidHint ?? '' }));
}

/** Chuỗi từ `code` xuống gốc yếu nhất. */
export function rootChainFor(
  code: string,
  byCode: Record<string, SkillMastery>,
  skills: Record<string, Skill> = SKILL_BY_CODE,
  misconceptions: Record<string, Misconception> = MISCONCEPTIONS,
): string[] {
  const chain = [code];
  const seen = new Set(chain);
  let cur = code;
  for (;;) {
    const weak = (skills[cur]?.prereqs ?? []).filter((c) => !seen.has(c) && isWeak(byCode[c]));
    if (!weak.length) break;
    weak.sort((a, b) => byCode[a].p - byCode[b].p || byCode[b].attempts - byCode[a].attempts || a.localeCompare(b));
    cur = weak[0];
    chain.push(cur);
    seen.add(cur);
  }
  if (chain.length === 1) {
    for (const mc of topMisconceptions(byCode[code]?.misconceptions ?? {}, misconceptions, 3)) {
      const r = misconceptions[mc.code]?.rootSkill;
      if (r && !seen.has(r) && isWeak(byCode[r])) {
        chain.push(r);
        break;
      }
    }
  }
  return chain;
}

/** Lỗ hổng của một HS, ưu tiên cao trước. */
export function findGaps(
  masteries: SkillMastery[],
  skills: Record<string, Skill> = SKILL_BY_CODE,
  misconceptions: Record<string, Misconception> = MISCONCEPTIONS,
): KnowledgeGap[] {
  const byCode: Record<string, SkillMastery> = {};
  for (const m of masteries) byCode[m.skillCode] = m;
  const gaps: KnowledgeGap[] = [];
  for (const m of masteries) {
    if (m.level !== 'can-on') continue;
    const chain = rootChainFor(m.skillCode, byCode, skills, misconceptions);
    const misTotal = Object.values(m.misconceptions).reduce((a, b) => a + b, 0);
    const priority = (GAP_P - m.p + 0.4) * (1 + Math.log2(1 + m.attempts) / 4) + 0.2 * (chain.length - 1) + 0.05 * Math.min(misTotal, 6);
    gaps.push({
      userId: m.userId,
      skillCode: m.skillCode,
      rootSkill: chain[chain.length - 1],
      rootChain: chain,
      level: m.level,
      p: m.p,
      attempts: m.attempts,
      priority: Math.round(priority * 1000) / 1000,
      topMisconceptions: topMisconceptions(m.misconceptions, misconceptions),
      evidence: m.recentWrong,
    });
  }
  // Gốc chung của nhiều lỗ hổng được ưu tiên hơn.
  const rootCount: Record<string, number> = {};
  for (const g of gaps) rootCount[g.rootSkill] = (rootCount[g.rootSkill] ?? 0) + 1;
  for (const g of gaps) g.priority = Math.round((g.priority + 0.1 * (rootCount[g.rootSkill] - 1)) * 1000) / 1000;
  return gaps.sort((a, b) => b.priority - a.priority || a.skillCode.localeCompare(b.skillCode));
}
